// Format song release data from Google Sheets or Webhook
const items = $input.all();
const formattedSongs = [];

for (const item of items) {
  const row = item.json.body || item.json;
  const title = row.song_name || row.title;
  if (!title || title.trim() === '' || title.includes('MASTER SONGS') || title.includes('SONG INFO')) {
    continue;
  }

  const artist = row.artist || 'Rasa Productions';
  const duration = row.duration || '4:30';
  const releaseDate = row.release_date || row.releaseDate || new Date().toISOString().split('T')[0];
  const cover = row.poster_drive_url || row.cover || '/covers/default.webp';
  const audio = row.audio_drive_url || row.audio || '';

  const platforms = {
    spotify: row.spotify_url || row.platforms?.spotify || '',
    youtube: row.youtube_music_url || row.youtube_url || row.platforms?.youtube || '',
    apple: row.apple_music_url || row.platforms?.apple || '',
    amazon: row.amazon_url || row.platforms?.amazon || '',
    deezer: row.deezer_url || row.platforms?.deezer || '',
    jiosaavn: row.jiosaavn_url || row.platforms?.jiosaavn || '',
    soundcloud: row.soundcloud_url || row.platforms?.soundcloud || '',
    shazam: row.shazam_url || row.platforms?.shazam || ''
  };

  const lyricTelugu = row.lyric_snippet_telugu || '';
  const lyricEnglish = row.lyric_snippet_english || '';
  let lyricSnippet = '';
  if (lyricTelugu && lyricEnglish) {
    lyricSnippet = `${lyricTelugu} • ${lyricEnglish}`;
  } else {
    lyricSnippet = lyricTelugu || lyricEnglish || '';
  }

  formattedSongs.push({
    id: title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
    title,
    artist,
    duration,
    genre: row.genre || 'Christian Devotional',
    language: row.language || 'Telugu',
    releaseDate,
    cover,
    audio,
    lyricSnippet,
    platforms
  });
}

return formattedSongs.map(s => ({ json: s }));
